/// Sequence `Microphone Test (with Trigger)`.
Future<void> microphoneTestWithTrigger() async {
  final locals = _MicrophoneTestWithTriggerLocals();

  try {
    // Example demonstrates Frequency domain measurements of captured Analog(Audio) signal generated by Analog Output(generates sine wave tones) module with Hardware Trigger
