      'Signal Voltage Generation\\DAQ_SV Gen Configure and Generate.vi',
      inputs: {
        'DAQmx Task In': locals.signalVoltageGenTask,
        'Range and Terminal Settings.Min Voltage (V)': -2,
        'Range and Terminal Settings.Max Voltage (V)': 2,
        'Signal Generation Settings.Generation Type': 0,
        'Signal Generation Settings.Generation Time (s)': 0.1,
        'Signal Generation Settings.Voltage Offset (v)': 0,
        'Signal Generation Settings.Single Tone Settings.Waveform Type': 0,
        'Signal Generation Settings.Single Tone Settings.Frequency (Hz)': 1000,
        'Signal Generation Settings.Single Tone Settings.Amplitude (V)': 1,
      },
    ); // Signal Voltage Generation - Configure and generate Sine tones in TS Analog Out
    locals.signalVoltageGenTask = outputs4['DAQmx Task Out'];
